scripts.Move_Connected:
(if ((eq #move #this)
     (block 
          (enum (WAGetInPlay #target) Page
                (if ((and (WAIsSpecial Page)
                          (WAHasModifier Page 'Gameplan)
                     )
                     (block 
                          (WAMessage -1 (WAGetName Page) "has been removed by" (WAGetName #this))
                          (WAOutOfPlay Page)
                     )
                    )
                )
          )
          (sett Index (count (WAGetHand #target)))
          (sett NumDitched 0)
          (loop (greater Index 0)
                (block 
                     (sett Card (item (WAGetHand #target) Index))
                     (if ((WAIsSpecial Card)
                          (block 
                               (WAMessage (WAGetOwner #target) (WAGetName #this) "has forced you to ditch" (WAGetName Card))
                               (WADitchPage #target (subtract Index 1))
                               (sett NumDitched (add NumDitched 1))
                          )
                         )
                     )
                     (sett Index (subtract Index 1))
                )
          )
          (if ((greater NumDitched 0)
               (WAMessage (WAGetOwner #this) (WAGetName #this) "has forced your opponent to ditch" NumDitched "pages from hand.")
              )
              (True
               (WAMessage (WAGetOwner #this) (WAGetName #this) "ditched no pages from your opponent's hand.")
              )
          )
          (if ((eq (WARandom 1 2) 1)
               (WAMessage -1 "Jim Ross: What an amazing display!")
              )
              (True
               (WAMessage -1 "Jim Ross: Incredible!" (WAGetName #target) "is in a world of hurt!")
              )
          )
          (if ((eq (WARandom 1 3) 1)
               (WAMessage -1 "Lawler: Unbelievable!!")
